    19	enum DtdPhase { Start, Main, Quote, Subset, SubsetQuote, Lt, Bang, BangDash, Comment, Pi }
    20	#[derive(Clone, Copy)]
    21	struct Dtd { phase: DtdPhase, quote: u8, run: u8, subset_closed: bool }
    22	impl Default for Dtd { fn default() -> Self { Self { phase: DtdPhase::Start, quote: 0, run: 0, subset_closed: false } } }
    23	impl Dtd {
    24	    fn step(&mut self, c: u8) -> Result<bool, ()> {
    25	        loop { match self.phase {
    26	            DtdPhase::Start => { if !is_xml_whitespace(c) { return Err(()) } self.phase=DtdPhase::Main; return Ok(false) },
    27	            DtdPhase::Main => match c { b'"'|b'\''=>{self.quote=c;self.phase=DtdPhase::Quote},b'['=>{if self.subset_closed{return Err(())}self.phase=DtdPhase::Subset},b'>'=>return Ok(true),b'<'=>return Err(()),_=>{} },
    28	            DtdPhase::Quote=>if c==self.quote{self.phase=DtdPhase::Main},
    29	            DtdPhase::Subset=>match c {b'"'|b'\''=>{self.quote=c;self.phase=DtdPhase::SubsetQuote},b'<'=>self.phase=DtdPhase::Lt,b']'=>{self.subset_closed=true;self.phase=DtdPhase::Main},_=>{}},
    30	            DtdPhase::SubsetQuote=>if c==self.quote{self.phase=DtdPhase::Subset},
    31	            DtdPhase::Lt=>match c{b'!'=>{self.phase=DtdPhase::Bang;return Ok(false)},b'?'=>{self.run=0;self.phase=DtdPhase::Pi;return Ok(false)},_=>{self.phase=DtdPhase::Subset;continue}},
    32	            DtdPhase::Bang=>if c==b'-'{self.phase=DtdPhase::BangDash;return Ok(false)}else{self.phase=DtdPhase::Subset;continue},
    33	            DtdPhase::BangDash=>if c==b'-'{self.run=0;self.phase=DtdPhase::Comment;return Ok(false)}else{self.phase=DtdPhase::Subset;continue},
    34	            DtdPhase::Comment=>if c==b'-'{self.run=(self.run+1).min(2)}else if c==b'>'&&self.run>=2{self.phase=DtdPhase::Subset}else{self.run=0},
    35	            DtdPhase::Pi=>if c==b'>'&&self.run==1{self.phase=DtdPhase::Subset}else{self.run=u8::from(c==b'?')},
    36	        } return Ok(false) }
    37	    }
    38	}
