    64	impl<'a> XmlTokenStream<'a> {
    65	    pub fn new(source:&'a [u8],max_storage_bytes:usize)->Result<Self,StreamStatus>{
    66	        Self::construct(source,max_storage_bytes,false)
    67	    }
    68	    pub fn new_visitor(source:&'a [u8])->Result<Self,StreamStatus>{
    69	        let scratch=MAX_ATTRIBUTES_PER_ELEMENT.checked_add(1).and_then(|n|n.checked_mul(size_of::<XmlToken>())).ok_or(StreamStatus::Failed)?;
    70	        Self::construct(source,scratch,true)
    71	    }
    72	    fn construct(source:&'a [u8],max_storage_bytes:usize,visitor_mode:bool)->Result<Self,StreamStatus>{
    73	        if source.len()>MAX_LARGE_INPUT_BYTES||(!visitor_mode&&max_storage_bytes<size_of::<XmlToken>()){return Err(StreamStatus::Failed)}
    74	        let limits=XmlLimits{input_bytes:MAX_LARGE_INPUT_BYTES,..XmlLimits::default()};
    75	        let mut tag_scratch=Vec::new();
    76	        if visitor_mode&&tag_scratch.try_reserve_exact(MAX_ATTRIBUTES_PER_ELEMENT+1).is_err(){return Err(StreamStatus::Failed)}
    77	        let mut open_names=Vec::new();if open_names.try_reserve_exact(MAX_DEPTH).is_err(){return Err(StreamStatus::Failed)}
    78	        let cursor=if source.starts_with(b"\xef\xbb\xbf"){3}else{0};
    79	        Ok(Self{source,limits,result:XmlResult::default(),tokens:Vec::new(),tag_scratch,storage_limit:max_storage_bytes,visitor_mode,
    80	            cursor,parse_limit:cursor,char_cursor:0,chars_complete:false,depth:0,roots:0,total_attrs:0,open_names,
    81	            pending:Pending::None,tag:None,doctype_seen:false,complete:false,canceled:false,taken:false})
    82	    }
