    98	    fn step_inner<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C,mut visitor:Option<&mut dyn FnMut(&XmlToken)->bool>)->StreamStatus{
    99	        if self.canceled{return StreamStatus::Canceled} if self.result.diagnostic.category!=XmlError::None{return StreamStatus::Failed}
   100	        if budget==0{return StreamStatus::Failed} if self.complete{return StreamStatus::Complete}
   101	        if self.visitor_mode&&visitor.is_none(){return StreamStatus::Failed}
   102	        if cancel(){self.canceled=true;return StreamStatus::Canceled}
   103	        let budget=budget.min(STEP_CAP);let char_initial=self.char_cursor;
   104	        if !self.scan_chars(budget,cancel){return self.failed_or_canceled()}
   105	        if !self.chars_complete{return StreamStatus::Ok}
   106	        let char_work=self.char_cursor.saturating_sub(char_initial);if char_work>=budget{return StreamStatus::Ok}
   107	        let parse_budget=budget-char_work;let initial=self.frontier();
   108	        let limit=initial.saturating_add(parse_budget).min(self.source.len());self.parse_limit=limit;
   109	        while self.cursor<self.source.len()&&self.frontier().saturating_sub(initial)<parse_budget {
   110	            if cancel(){self.canceled=true;return StreamStatus::Canceled}
   111	            let before=self.frontier();
   112	            if !self.parse_next(limit,&mut visitor,cancel){return self.failed_or_canceled()}
   113	            if self.frontier()==before{break}
   114	        }
   115	        if self.cursor==self.source.len()&&matches!(self.pending,Pending::None)&&self.tag.is_none(){
   116	            if self.depth!=0||self.roots==0{self.fail(XmlError::IncompleteDocument,self.source.len());return self.failed_or_canceled()}
   117	            self.complete=true;
   118	        }
   119	        if self.complete{StreamStatus::Complete}else{StreamStatus::Ok}
   120	    }
   121	    fn scan_chars<C:FnMut()->bool>(&mut self,budget:usize,cancel:&mut C)->bool{
   122	        let end=self.char_cursor.saturating_add(budget).min(self.source.len());
   123	        while self.char_cursor<end{
   124	            if cancel(){self.canceled=true;return false}
   125	            let at=self.char_cursor;let lead=self.source[at];
   126	            let width=match lead{0x00..=0x7f=>1,0xc2..=0xdf=>2,0xe0..=0xef=>3,0xf0..=0xf4=>4,_=>1};
   127	            if at.saturating_add(width)>end&&end<self.source.len(){break}
   128	            let Some((cp,next))=utf8_next(self.source,at)else{self.fail(XmlError::InvalidUtf8,at);return false};
   129	            if next>end&&end<self.source.len(){break}
   130	            if !is_xml_char(cp){self.fail(XmlError::InvalidCharacter,at);return false}
   131	            self.char_cursor=next;
   132	        }
   133	        if self.char_cursor==self.source.len(){self.chars_complete=true}
   134	        true
   135	    }
   136	    fn parse_next<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
   137	        if self.tag.is_some(){return self.parse_tag(limit,visitor,cancel)}
   138	        if !matches!(self.pending,Pending::None){return self.parse_pending(limit,visitor,cancel)}
   139	        let p=self.cursor;if p>=limit{return true}
   140	        if self.source[p]!=b'<'{self.pending=Pending::Text{start:p,pos:p,nonspace:false,first_nonspace:0,reference:None};return self.parse_pending(limit,visitor,cancel)}
   141	        if self.source.get(p..p.saturating_add(4))==Some(b"<!--"){self.pending=Pending::Comment{start:p,pos:p+4,dashes:0};return self.parse_pending(limit,visitor,cancel)}
   142	        if self.source.get(p..p.saturating_add(9))==Some(b"<![CDATA["){self.pending=Pending::Cdata{start:p,pos:p+9,brackets:0};return self.parse_pending(limit,visitor,cancel)}
   143	        if self.source.get(p..p.saturating_add(9))==Some(b"<!DOCTYPE"){
   144	            if self.depth!=0||self.roots!=0||self.doctype_seen{self.fail(XmlError::MalformedSyntax,p);return false}
   145	            self.pending=Pending::Doctype{start:p,pos:p+9,state:Dtd::default()};return self.parse_pending(limit,visitor,cancel)
   146	        }
   147	        if self.source.get(p..p.saturating_add(8))==Some(b"<!ENTITY"){self.fail(XmlError::UnsupportedDtd,p);return false}
   148	        if self.source.get(p..p.saturating_add(2))==Some(b"<?"){self.pending=Pending::Pi{start:p,pos:p+2,name_scan:None,name:None,declaration:false,data:None,separating:false,question:false};return self.parse_pending(limit,visitor,cancel)}
   149	        if self.source.get(p..p.saturating_add(2))==Some(b"</"){self.tag=Some(TagState::new(p,true));return self.parse_tag(limit,visitor,cancel)}
   150	        if self.source.get(p..p.saturating_add(2))==Some(b"<!"){self.fail(XmlError::MalformedSyntax,p);return false}
   151	        self.tag=Some(TagState::new(p,false));self.parse_tag(limit,visitor,cancel)
   152	    }
   153	    fn parse_pending<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
   154	        let pending=core::mem::replace(&mut self.pending,Pending::None);
   155	        match pending{
   156	            Pending::None=>true,
   157	            Pending::Text{start,mut pos,mut nonspace,mut first_nonspace,mut reference}=>{
   158	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Text{start,pos,nonspace,first_nonspace,reference};self.canceled=true;return false}
   159	                    if self.source[pos]==b'<'{break}
   160	                    if self.source.get(pos..pos+3)==Some(b"]]>"){self.fail(XmlError::MalformedSyntax,pos);return false}
   161	                    if self.source[pos]==b'&'{let scan=reference.get_or_insert_with(||RefScan::new(pos));match reference_step(self.source,scan,limit){Ok(Some(end))=>{pos=end;reference=None},Ok(None)=>break,Err((e,at))=>{self.fail(e,at);return false}}}
   162	                    else{if !is_xml_whitespace(self.source[pos])&&!nonspace{nonspace=true;first_nonspace=pos}pos+=1}
   163	                }
   164	                if pos<self.source.len()&&self.source[pos]==b'<'{return self.finish_text(start,pos,nonspace,first_nonspace,visitor)}
   165	                if pos==self.source.len(){return self.finish_text(start,pos,nonspace,first_nonspace,visitor)}
   166	                self.pending=Pending::Text{start,pos,nonspace,first_nonspace,reference};true
   167	            }
   168	            Pending::Comment{start,mut pos,mut dashes}=>{
   169	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Comment{start,pos,dashes};self.canceled=true;return false}
   170	                    let c=self.source[pos];if dashes==2{if c!=b'>'{self.fail(XmlError::MalformedSyntax,pos-2);return false}let end=pos+1;let t=XmlToken{kind:TokenKind::Comment,source:span(start,end),value:span(start+4,pos-2),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}if !self.emit(t,start,visitor){return false}self.cursor=end;return true}
   171	                    dashes=if c==b'-'{dashes+1}else{0};pos+=1;
   172	                }
   173	                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Comment{start,pos,dashes};true
   174	            }
   175	            Pending::Cdata{start,mut pos,mut brackets}=>{
   176	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Cdata{start,pos,brackets};self.canceled=true;return false}
   177	                    let c=self.source[pos];if c==b'>'&&brackets>=2{if self.depth==0{self.fail(XmlError::MalformedSyntax,start);return false}
   178	                        if pos-2-(start+9)>self.limits.text_run_bytes{self.fail(XmlError::TextLimit,start+9);return false}let end=pos+1;let t=XmlToken{kind:TokenKind::Cdata,source:span(start,end),value:span(start+9,pos-2),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}if !self.emit(t,start,visitor){return false}self.cursor=end;return true}brackets=if c==b']'{(brackets+1).min(2)}else{0};pos+=1;
   179	                }
   180	                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Cdata{start,pos,brackets};true
   181	            }
   182	            Pending::Doctype{start,mut pos,mut state}=>{
   183	                while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Doctype{start,pos,state};self.canceled=true;return false}
   184	                    match state.step(self.source[pos]){Ok(done)=>{pos+=1;if done{let t=XmlToken{kind:TokenKind::Doctype,source:span(start,pos),depth:self.depth,..XmlToken::default()};if !self.count_node(start){return false}self.doctype_seen=true;if !self.emit(t,start,visitor){return false}self.cursor=pos;return true}},Err(())=>{self.fail(XmlError::MalformedSyntax,pos);return false}}
   185	                }
   186	                if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Doctype{start,pos,state};true
   187	            }
   188	            Pending::Pi{start,mut pos,mut name_scan,mut name,mut declaration,mut data,mut separating,mut question}=>{
   189	                if name.is_none(){let scan=name_scan.get_or_insert(NameScan{start:pos,pos,first_colon:None});match scan_name(self.source,scan,limit,false){Ok(Some(parts))=>{name=Some(parts.name);pos=scan.pos;declaration=parts.name.slice(self.source)==Some(b"xml");let raw=parts.name.slice(self.source).unwrap_or_default();if !declaration&&raw.len()==3&&raw.eq_ignore_ascii_case(b"xml"){self.fail(XmlError::MalformedSyntax,start);return false}if declaration&&start!=0&&!(start==3&&self.source.starts_with(b"\xef\xbb\xbf")){self.fail(XmlError::MalformedSyntax,start);return false}},Ok(None)=>{if pos==self.source.len(){self.fail(XmlError::InvalidName,pos);return false}self.pending=Pending::Pi{start,pos:scan.pos,name_scan,name,declaration,data,separating,question};return true},Err((e,at))=>{self.fail(e,at);return false}}}
   190	                if data.is_none(){if pos>=limit{if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};return true}
   191	                    if !separating&&self.source.get(pos..pos.saturating_add(2))==Some(b"?>"){if declaration{self.fail(XmlError::MalformedSyntax,pos);return false}data=Some(pos)}
   192	                    else if !separating&&!is_xml_whitespace(self.source[pos]){self.fail(XmlError::MalformedSyntax,pos);return false}
   193	                    else{separating=true;while pos<limit&&pos<self.source.len()&&is_xml_whitespace(self.source[pos]){pos+=1}if pos==limit&&pos<self.source.len(){self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};return true}data=Some(pos)}
   194	                }
   195	                let begin=data.unwrap_or(pos);if data.is_none(){pos=begin}
   196	                let mut end=None;while pos<limit&&pos<self.source.len(){if cancel(){self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};self.canceled=true;return false}let c=self.source[pos];if c==b'>'&&question{end=Some(pos+1);break}question=c==b'?';pos+=1}
   197	                let Some(end)=end else{if pos==self.source.len(){self.fail(XmlError::MalformedSyntax,start);return false}self.pending=Pending::Pi{start,pos,name_scan,name,declaration,data,separating,question};return true};
   198	                let end_start=end-2;let n=name.unwrap_or_default();let t=XmlToken{kind:if declaration{TokenKind::Declaration}else{TokenKind::ProcessingInstruction},source:span(start,end),name:n,value:span(begin,end_start),depth:self.depth,..XmlToken::default()};
   199	                if declaration{if let Err(crate::tokenizer::Fault(e,at))=validate_declaration(self.source,t.value){self.fail(e,at);return false}}else if !self.count_node(start){return false}
   200	                if !self.emit(t,start,visitor){return false}self.cursor=end;true
   201	            }
   202	        }
   203	    }
   204	    fn finish_text(&mut self,start:usize,end:usize,nonspace:bool,first:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>)->bool{
   205	        if end-start>self.limits.text_run_bytes{self.fail(XmlError::TextLimit,start);return false}
   206	        if self.depth==0&&nonspace{self.fail(XmlError::MalformedSyntax,first);return false}
   207	        if (self.depth!=0||nonspace)&&!self.count_node(start){return false}let source=span(start,end);let t=XmlToken{kind:TokenKind::Text,source,value:source,depth:self.depth,..XmlToken::default()};
   208	        if !self.emit(t,start,visitor){return false}self.cursor=end;true
   209	    }
