   211	    fn parse_tag<C:FnMut()->bool>(&mut self,limit:usize,visitor:&mut Option<&mut dyn FnMut(&XmlToken)->bool>,cancel:&mut C)->bool{
   212	        let Some(mut t)=self.tag.take()else{return true};
   213	        while t.pos<limit&&t.pos<self.source.len(){if cancel(){self.tag=Some(t);self.canceled=true;return false}
   214	            match t.phase{
   215	                TagPhase::Prefix=>{let expected=if t.closing{if t.pos==t.start{b'<' }else{b'/'} }else{b'<'};if self.source[t.pos]!=expected{self.fail(XmlError::MalformedSyntax,t.pos);return false}t.pos+=1;if (t.closing&&t.pos==t.start+2)||(!t.closing&&t.pos==t.start+1){t.phase=TagPhase::Name;t.name_scan=Some(NameScan{start:t.pos,pos:t.pos,first_colon:None});}},
   216	                TagPhase::Name=>{let qname=true;let Some(scan)=t.name_scan.as_mut()else{self.fail(XmlError::InvalidName,t.pos);return false};match scan_name(self.source,scan,limit,qname){Ok(Some(parts))=>{t.pos=scan.pos;t.name=Some(parts);if t.closing{let n=parts.name;if self.depth==0||self.open_names.last().and_then(|s|s.slice(self.source))!=n.slice(self.source){self.fail(XmlError::MismatchedTag,t.start);return false}t.phase=TagPhase::EndBetween}else{
   217	                    if self.depth==0{if self.roots!=0{self.fail(XmlError::MultipleRoots,t.start);return false}self.roots+=1}
   218	                    if self.depth>=self.limits.nesting_depth||self.depth>=MAX_DEPTH{self.fail(XmlError::DepthLimit,t.start);return false}if !self.count_node(t.start){return false}
   219	                    let tok=XmlToken{kind:TokenKind::StartElement,source:span(t.start,t.pos),name:parts.name,prefix:parts.prefix,local_name:parts.local,depth:self.depth,..XmlToken::default()};
   220	                    t.token_index=self.tag_len();if !self.stage_tag(tok,t.start){return false}t.local_attrs=0;t.phase=TagPhase::Between;t.separated=false;}}
   221	                    Ok(None)=>{self.tag=Some(t);return true},Err((e,at))=>{self.fail(e,at);return false}}},
   222	                TagPhase::Between=>{while t.pos<limit&&t.pos<self.source.len()&&is_xml_whitespace(self.source[t.pos]){t.pos+=1;t.separated=true}if t.pos>=limit&&t.pos<self.source.len(){self.tag=Some(t);return true}
